<div class="modal fade" id="deleteModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5>Confirm deletion</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">Are you sure you want to delete this record?</div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Cancel</button><form id="deleteForm" method="POST">@csrf @method('DELETE')<button class="btn btn-danger">Delete</button></form></div></div></div></div>
@push('scripts')<script>document.addEventListener('click',e=>{const b=e.target.closest('[data-delete]');if(!b)return;document.getElementById('deleteForm').action=b.dataset.delete;new bootstrap.Modal(document.getElementById('deleteModal')).show();});</script>@endpush
